from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1]
def check(ok,label):
    if not ok: print('FAIL - '+label);sys.exit(1)
    print('PASS - '+label)
main=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
php=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
reg=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
js=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.24.0.js').read_text()
helper=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-project-diff-v1.js').read_text()
css=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/css/workspace-v0.24.0.css').read_text()
manifest=json.loads((ROOT/'release-manifest-v0.24.0.json').read_text())
record=json.loads((ROOT/'registry/workspace-product-record-v0.24.0.json').read_text())
check('Version: 0.24.0' in main,'plugin version')
check("define('SC_WORKSPACE_VERSION', '0.24.0')" in main,'runtime version')
check(manifest['version']=='0.24.0' and manifest['previous_version']=='0.23.0','manifest release lineage')
check(manifest['release_name']=='Project Diff & Change Review','release name')
check(manifest['storage_schema_version']==23 and manifest['project_schema']=='sc-workspace-project/11.0','schema-stable storage 23 / project 11.0')
check("'/change-review-contract'" in php and 'public function change_review_contract()' in php,'change review REST contract')
check(manifest['change_review']['schema']=='sc-workspace-change-review/1.0','change review schema')
check('data-scw-workspace-view="changes"' in php and 'data-scw-workspace-section="changes"' in php,'Changes workspace view')
check('SCWorkspaceProjectDiff' in helper and 'compareProjects' in helper,'deterministic project diff engine')
check('Evidence assessments' in helper and 'Analysis assumptions' in helper and 'Decisions' in helper,'evidence assumptions decisions comparison')
check('Traceability relationships' in helper and 'Canvas relationships' in helper,'relationship comparison')
check(not manifest['change_review']['hidden_change_score'] and not manifest['change_review']['automatic_apply'] and not manifest['change_review']['automatic_merge'],'no hidden score / no automatic reconciliation')
check('data-scw-change-export' in php and 'change-review-' in js,'portable review JSON export')
check("review.textContent='Review changes'" in js,'restore-point to Change Review bridge')
check("const VERSION_HISTORY_SCHEMA = 'sc-workspace-version-history/1.0'" in js and "const RESTORE_POINT_SCHEMA = 'sc-workspace-restore-point/1.0'" in js,'v0.23 restore points retained')
check('state.accountPersistence = normalizeAccountPersistence(raw.accountPersistence, state.projects);' in js and 'state.crossDeviceSync = normalizeCrossDeviceSync(raw.crossDeviceSync, state.projects);' in js,'account/sync normalization retained')
check("const CROSS_DEVICE_SYNC_SCHEMA = 'sc-workspace-cross-device-sync/1.0'" in js and "'/sync-contract'" in php,'conflict-safe sync retained')
check("const ACCOUNT_PERSISTENCE_SCHEMA = 'sc-workspace-account-persistence/1.0'" in js and "'/account-persistence-contract'" in php,'account persistence retained')
check('@media(prefers-reduced-motion:reduce)' in css and '@media(forced-colors:active)' in css and ':focus-visible' in css,'accessibility hardening retained')
check('/* v0.24.0 — Project Diff & Change Review */' in css,'change review visual layer')
check(manifest['canonical_library_path']=='/knowledge-libraries/' and '/knowledge-libraries/' in php,'canonical Knowledge Library route')
check(record['public_version']=='0.24.0' and record['previous_version']=='0.23.0','registry record lineage')
check("BACKUP_KEY = 'sc_workspace_registry_backup_v0240'" in reg and "LEGACY_PENDING_KEY_V0230 = 'sc_workspace_registry_pending_v0230'" in reg,'registry pending/backup lineage')
